use runen_numeric_oracle::{
    BinaryFormat, BinaryValueFixture, ExactDyadic, RoundedBinaryValue, Sign, round_dyadic,
};

// Finite expected values below are independently generated by GNU MPFR 4.2.2.
// The checked regeneration program is `../reference/generate_sine_mpfr.c`.
// MPFR is verification instrumentation only; Runen semantics remain owned by
// `spec/language/core/numerics/floating-point.md`.
//
// Generation uses target precision p, MPFR emin = Runen emin - p + 2,
// MPFR emax = Runen emax + 1, exact dyadic inputs, `mpfr_sin` with
// MPFR_RNDN, and `mpfr_subnormalize` with the returned ternary value and
// MPFR_RNDN. Normal `cargo validate` does not execute or depend on MPFR.

const POS: Sign = Sign::Positive;
const NEG: Sign = Sign::Negative;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ReferenceCase {
    input: ExactDyadic,
    expected: RoundedBinaryValue,
}

impl ReferenceCase {
    const fn subnormal(
        input_sign: Sign,
        input_magnitude: u128,
        input_exponent: i32,
        expected_sign: Sign,
        expected_significand: u128,
    ) -> Self {
        Self {
            input: ExactDyadic::from_parts(input_sign, input_magnitude, input_exponent),
            expected: RoundedBinaryValue::Subnormal {
                sign: expected_sign,
                significand: expected_significand,
            },
        }
    }

    const fn normal(
        input_sign: Sign,
        input_magnitude: u128,
        input_exponent: i32,
        expected_sign: Sign,
        expected_significand: u128,
        expected_exponent: i32,
    ) -> Self {
        Self {
            input: ExactDyadic::from_parts(input_sign, input_magnitude, input_exponent),
            expected: RoundedBinaryValue::Normal {
                sign: expected_sign,
                significand: expected_significand,
                exponent: expected_exponent,
            },
        }
    }
}

