fn tiny_format() -> BinaryFormat {
    BinaryFormat::new(4, -2, 2).expect("valid tiny reference format")
}

fn stress_format() -> BinaryFormat {
    BinaryFormat::new(16, -20, 200).expect("valid stress reference format")
}

fn tiny_finite_domain() -> Vec<ExactDyadic> {
    let mut domain = Vec::with_capacity(94);
    for sign in [POS, NEG] {
        for significand in 1..8 {
            domain.push(ExactDyadic::from_parts(sign, significand, -5));
        }
        for exponent in -2..=2 {
            for significand in 8..16 {
                domain.push(ExactDyadic::from_parts(sign, significand, exponent - 3));
            }
        }
    }
    domain
}

fn exact_value_of_encoded(precision: u32, emin: i32, value: RoundedBinaryValue) -> ExactDyadic {
    let precision_tail = i32::try_from(precision - 1).expect("fixture precision fits i32");
    match value {
        RoundedBinaryValue::Subnormal { sign, significand } => {
            ExactDyadic::from_parts(sign, significand, emin - precision_tail)
        }
        RoundedBinaryValue::Normal {
            sign,
            significand,
            exponent,
        } => ExactDyadic::from_parts(sign, significand, exponent - precision_tail),
        RoundedBinaryValue::Zero(_) | RoundedBinaryValue::Infinity(_) => {
            panic!("finite sine corpus must contain only nonzero finite outputs")
        }
    }
}

fn assert_reference_output_is_target_value(
    format: BinaryFormat,
    precision: u32,
    emin: i32,
    case: ReferenceCase,
) {
    let exact = exact_value_of_encoded(precision, emin, case.expected);
    assert_eq!(
        round_dyadic(format, exact),
        Ok(case.expected),
        "reference output is not an exact value of its target format for input {:?}",
        case.input
    );
}

#[test]
fn tiny_reference_corpus_covers_every_signed_nonzero_finite_value_once() {
    let domain = tiny_finite_domain();
    assert_eq!(domain.len(), 94);
    assert_eq!(TINY_FINITE_CASES.len(), domain.len());

    for input in domain {
        let occurrences = TINY_FINITE_CASES
            .iter()
            .filter(|case| case.input == input)
            .count();
        assert_eq!(
            occurrences, 1,
            "tiny reference input {:?} must occur exactly once",
            input
        );
    }
}

#[test]
fn finite_reference_outputs_are_exact_target_format_values() {
    for &case in TINY_FINITE_CASES {
        assert_reference_output_is_target_value(tiny_format(), 4, -2, case);
    }
    for &case in STRESS_CASES {
        assert_reference_output_is_target_value(stress_format(), 16, -20, case);
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SpecialSineReference {
    Value(RoundedBinaryValue),
    NaNClass,
}

fn special_sine_reference(input: BinaryValueFixture) -> Option<SpecialSineReference> {
    match input {
        BinaryValueFixture::Zero(sign) => {
            Some(SpecialSineReference::Value(RoundedBinaryValue::Zero(sign)))
        }
        BinaryValueFixture::Infinity(_) | BinaryValueFixture::NaNClass => {
            Some(SpecialSineReference::NaNClass)
        }
        BinaryValueFixture::Finite(_) => None,
    }
}

#[test]
fn special_value_reference_matches_accepted_sine_classes() {
    assert_eq!(
        special_sine_reference(BinaryValueFixture::Zero(POS)),
        Some(SpecialSineReference::Value(RoundedBinaryValue::Zero(POS)))
    );
    assert_eq!(
        special_sine_reference(BinaryValueFixture::Zero(NEG)),
        Some(SpecialSineReference::Value(RoundedBinaryValue::Zero(NEG)))
    );
    assert_eq!(
        special_sine_reference(BinaryValueFixture::Infinity(POS)),
        Some(SpecialSineReference::NaNClass)
    );
    assert_eq!(
        special_sine_reference(BinaryValueFixture::Infinity(NEG)),
        Some(SpecialSineReference::NaNClass)
    );
    assert_eq!(
        special_sine_reference(BinaryValueFixture::NaNClass),
        Some(SpecialSineReference::NaNClass)
    );
}
